with fields as (select jsonb_agg(jsonb_build_object('key',key,'sectionKey','gastrointestinal','label',label,'type','text','sequence',sequence,'required',false,'accessibilityLabel',label,'helpText','Legacy three-state Review of Systems value: Yes, No, or N/A.','maxLength',3,'minimum',null,'maximum',null,'precision',null,'unit',null,'codeSystem',null,'options',jsonb_build_array(jsonb_build_object('value','Yes','label','Yes'),jsonb_build_object('value','No','label','No'),jsonb_build_object('value','N/A','label','N/A')),'repeatMinimum',null,'repeatMaximum',null,'children','[]'::jsonb,'readOnly',false) order by sequence) value from (values ('dysphagia','Dysphagia',10),('heartburn','Heartburn',20),('bloating','Bloating',30),('belching','Belching',40),('flatulence','Flatulence',50),('nausea','Nausea',60),('vomiting','Vomiting',70),('hematemesis','Hematemesis',80),('gastro_pain','Abdominal pain',90),('food_intolerance','Food intolerance',100),('hepatitis','Hepatitis',110),('jaundice','Jaundice',120),('hematochezia','Hematochezia',130),('changed_bowel','Changed bowel habits',140),('diarrhea','Diarrhea',150),('constipation','Constipation',160)) source(key,label,sequence)), schema as (select jsonb_build_object('stableKey','legacy.rosgastrointestinal','name','Review of Systems Gastrointestinal','purpose','Legacy Review of Systems gastrointestinal compatibility capture.','contextScope','encounter','owningService','clinical_operations','capability','encounters.auth_a','signaturePolicy','author-only','sections',jsonb_build_array(jsonb_build_object('key','gastrointestinal','title','Gastrointestinal','sequence',10,'description','Mapped from legacy form_ros gastrointestinal fields.')),'fields',value,'rules','[]'::jsonb) schema_json from fields)
update clinical_form_definitions set effective_revision=1,updated_at=now(),updated_by='legacy-adoption-seed' where stable_key='legacy.rosgastrointestinal' and effective_revision is null;
